// Un módulo con frontera, en un solo archivo: lo privado no se puede tocar desde afuera.
class Flota {
  #vehiculos = new Map([['AA111AA', { capacidad: 20, cargados: 15 }]]);   // decisión escondida: cómo se guardan
  lugarLibre(patente) {                                                     // API pública
    const v = this.#vehiculos.get(patente);
    return v ? v.capacidad - v.cargados : 0;
  }
  cargar(patente, bultos) {
    if (bultos > this.lugarLibre(patente)) throw new Error('no entra');     // la regla vive adentro
    this.#vehiculos.get(patente).cargados += bultos;
  }
}
const flota = new Flota();
console.log('lugar libre:', flota.lugarLibre('AA111AA'));
console.log('acceso directo a los datos:', flota.vehiculos, Object.keys(flota));
try { flota.cargar('AA111AA', 9); } catch (e) { console.log('cargar 9 ->', e.message); }
flota.cargar('AA111AA', 5);
console.log('lugar libre tras cargar 5:', flota.lugarLibre('AA111AA'));

