/** Reglas de frontera para el monolito modular (módulos: despachos, flota, tarifas, avisos). */
module.exports = {
  forbidden: [
    {
      name: 'solo-por-la-puerta',
      comment: 'Un módulo solo puede usar de otro lo que exporta su index.js.',
      severity: 'error',
      from: { path: '^src/([^/]+)/' },
      to: { path: '^src/([^/]+)/', pathNot: ['^src/$1/', '^src/[^/]+/index\\.js$'] },
    },
    {
      name: 'sin-ciclos',
      comment: 'Dos módulos que se necesitan mutuamente son en la práctica uno solo.',
      severity: 'error',
      from: {},
      to: { circular: true },
    },
    {
      name: 'avisos-no-depende-de-nadie',
      comment: 'avisos es una hoja: puede ser usado por todos pero no usa a otros módulos.',
      severity: 'error',
      from: { path: '^src/avisos/' },
      to: { path: '^src/(despachos|flota|tarifas)/' },
    },
  ],
  options: { doNotFollow: { path: 'node_modules' }, tsPreCompilationDeps: false },
};

const repo = require('./repo');
// Lugar libre de un vehículo.
function lugarLibre(patente) {
  const v = repo.buscar(patente);
  return v ? v.capacidad - v.cargados : 0;
}
function cargar(patente, bultos) { repo.buscar(patente).cargados += bultos; }
// Un vehículo solo se puede retirar si no tiene despachos abiertos.
function puedeRetirar(patente, despachosAbiertos) { return despachosAbiertos === 0; } // el dato llega de afuera
function existe(patente) { return Boolean(repo.buscar(patente)); }
module.exports = { lugarLibre, cargar, puedeRetirar, existe };

